function exerciseCard(x,index){const sol=solutionsByExercise[x.id];return `<article id="exercise-${x.id}" class="exerciseCard"><div class="exerciseHead"><span>EJERCICIO ${String(index+1).padStart(2,'0')}</span><h3>${esc(x.title)}</h3></div><div class="exerciseStatement">${formatStudyHtml(x.statement_html)}</div>${sol?`<details class="solutionCard"><summary>Ver respuesta</summary><div class="solutionSteps">${formatStudyHtml(sol.solution_html)}${sol.final_answer?`<div class="finalAnswer"><b>Resultado</b>${sol.final_answer}</div>`:''}${isAdmin()?`<small class="adminSolutionState">Admin · ${sol.student_visible?'Visible para alumnos':'Oculta para alumnos'}</small>`:''}</div></details>`:''}</article>`}
