const QUICK_GUIDES={1:{'cap-1':['Mirar → imaginar → escribir','<b>Macro:</b> lo observable. <b>Submicro:</b> partículas. <b>Simbólico:</b> fórmulas y ecuaciones.','Si una explicación mezcla escalas, separalas primero.'],'cap-2':['Movimiento y fuerzas','Más temperatura implica mayor <b>energía cinética</b>; un cambio de estado no cambia la identidad química.','¿Cambia la sustancia o la organización de sus partículas?'],'cap-3':['Intensivas vs. extensivas','<b>Densidad y temperatura</b> no dependen de cuánto hay; <b>masa y volumen</b> sí.','Si dividís la muestra, ¿la propiedad conserva su valor?'],'cap-4':['Fase no es componente','Una <b>fase</b> es una región uniforme; un <b>componente</b> es una sustancia presente.','Hielo + agua: dos fases, un componente.'],'cap-5':['Identidad química','Átomos, moléculas e iones son modelos distintos; una fórmula indica <b>qué</b> y <b>cuánto</b>.','NaCl sólido forma una red iónica, no moléculas aisladas.'],'cap-6':['Separar por una diferencia','Elegí por <b>tamaño, densidad, solubilidad o ebullición</b>.','Primero identificá la propiedad que distingue los componentes.'],'cap-7':['El porcentaje compara','<b>% m/m = masa del componente ÷ masa total × 100.</b>','El denominador es la masa total.']},2:{'1-del-atomo-indivisible-al-modelo-orbital':['Cada modelo resuelve una evidencia','Dalton → Thomson → Rutherford → Bohr → orbital: cada paso explica observaciones que el anterior no podía.','Son modelos con distinto alcance, no fotografías del átomo.'],'2-particulas-subatomicas-y-notacion-nuclear':['Z identifica; A contabiliza','<b>Z = protones.</b> <b>A = protones + neutrones.</b> La carga depende de protones y electrones.','Cambiar neutrones da un isótopo; cambiar electrones da un ion.'],'5-bohr-niveles-cuantizados-y-luz':['Bohr es el puente, no el final','La energía está <b>cuantizada</b>: los saltos entre niveles producen líneas del espectro. El modelo orbital luego reemplaza trayectorias por probabilidades.','La foto muestra líneas reales: el hidrógeno no emite todos los colores.'],'6-modelo-orbital-y-numeros-cuanticos':['Orbital ≠ órbita','Un orbital es una <b>región de probabilidad</b>. Los números cuánticos describen nivel, subnivel, orientación y espín.','s es esférico; p tiene dos lóbulos; d es más complejo.'],'7-configuracion-electronica':['Distribuir sin perder la cuenta','Llená por energía, respetá Pauli y Hund, y verificá que la suma sea <b>Z</b> en un átomo neutro.','Al mover Z, el simulador también identifica el elemento.'],'10-carga-nuclear-efectiva-y-propiedades-periodicas':['La posición permite predecir','En un período suelen aumentar <b>ionización</b> y <b>electronegatividad</b>; el <b>radio</b> disminuye. En un grupo aparecen nuevas capas.','Abrí la tabla flotante y compará datos reales.']}};
