function studySimulator(s){
 if(unit===1&&s.key==='cap-2')return `<section class="inlineSimulator" data-sim="states"><div class="simTitle"><span>SIMULADOR</span><h3>Estados de la materia</h3></div><div class="stateButtons"><button data-state="solid" class="active">Sólido</button><button data-state="liquid">Líquido</button><button data-state="gas">Gas</button></div><label>Temperatura relativa <input type="range" min="0" max="100" value="15" data-sim-input="temp"></label><div class="matterStage"><canvas data-matter-canvas aria-label="Simulador animado de partículas en sólido, líquido y gas"></canvas><div class="matterReadout"><span>Estado: <b data-matter-state>Sólido</b></span><span>Movimiento: <b data-matter-speed>vibración</b></span><span>Choques: <b data-matter-collisions>0</b></span></div></div><output data-sim-output></output></section>`;
 if(unit===1&&s.key==='cap-3')return `<section class="inlineSimulator" data-sim="density"><div class="simTitle"><span>SIMULADOR</span><h3>Laboratorio de densidad</h3></div><label>Masa (g) <input type="range" min="10" max="250" value="100" data-sim-input="mass"></label><label>Volumen (mL) <input type="range" min="10" max="200" value="80" data-sim-input="volume"></label><div class="densityScene"><div class="beaker"><span data-level></span></div><div class="scale">⚖ <b data-mass></b></div></div><output data-sim-output></output></section>`;
 if(unit===1&&s.key==='cap-7')return `<section class="inlineSimulator concentrationLab" data-sim="concentration"><div class="simTitle"><span>SIMULADOR</span><h3>Concentración en un vaso</h3><p>Compará qué significa porcentaje <b>masa/masa</b> y <b>masa/volumen</b>.</p></div><div class="stateButtons"><button data-concentration-type="mm" class="active">% m/m</button><button data-concentration-type="mv">% m/V</button></div><label><span data-solute-label>Masa de soluto: <b>20 g</b></span><input type="range" min="1" max="80" value="20" data-sim-input="solute"></label><label><span data-total-label>Masa de solución: <b>100 g</b></span><input type="range" min="50" max="250" value="100" data-sim-input="total"></label><div class="concentrationScene"><div class="solutionCup"><i data-concentration-fill></i><span data-concentration-dots></span></div><strong data-concentration-value>20 % m/m</strong></div><output data-sim-output></output></section>`;
 if(unit===2&&s.key==='2-particulas-subatomicas-y-notacion-nuclear')return `<section class="inlineSimulator atomBuilder" data-sim="atom"><div class="simTitle"><span>SIMULADOR</span><h3>Constructor de átomos e iones</h3><p>Las cantidades, el elemento, el isótopo y la carga son reales. La animación muestra una <b>nube de probabilidad</b>: los electrones no recorren órbitas planetarias.</p></div><label>Protones, Z: <b data-p-label>8</b><input type="range" min="1" max="20" value="8" data-sim-input="p"></label><label>Neutrones: <b data-n-label>8</b><input type="range" min="0" max="24" value="8" data-sim-input="n"></label><label>Electrones: <b data-e-label>8</b><input type="range" min="0" max="22" value="8" data-sim-input="e"></label><div class="atomScene" aria-label="Núcleo y nube electrónica probabilística"><div class="electronCloud" data-electron-cloud></div><div class="atomNucleus" data-atom-nucleus></div></div><div class="atomCounts"><span>p⁺ <b data-count-p></b></span><span>n⁰ <b data-count-n></b></span><span>e⁻ <b data-count-e></b></span></div><output data-sim-output></output></section>`;
 if(unit===2&&s.key==='7-configuracion-electronica')return `<section class="inlineSimulator" data-sim="configuration"><div class="simTitle"><span>SIMULADOR</span><h3>Configuración electrónica por elemento</h3><p>Mové el número atómico: vas a ver Z, el nombre del átomo y cómo se llenan sus subniveles.</p></div><label>Número atómico: <b data-z-label>8</b> <input type="range" min="1" max="20" value="8" data-sim-input="z"></label><div class="electronBoxes" data-electron-boxes></div><output data-sim-output></output></section>`;
 if(unit===2&&s.key==='10-carga-nuclear-efectiva-y-propiedades-periodicas')return `<section class="inlineSimulator" data-sim="trends"><div class="simTitle"><span>SIMULADOR</span><h3>¿Por qué cambian las propiedades periódicas?</h3><p>Compará elementos y mirá simultáneamente <b>capas</b>, <b>apantallamiento</b>, <b>carga nuclear efectiva</b>, radio y electronegatividad.</p></div><label>Elemento A <select data-sim-input="a"><option>Li</option><option>Na</option><option>Mg</option><option>Al</option><option>Si</option><option>Cl</option><option>K</option></select></label><label>Elemento B <select data-sim-input="b"><option>Cl</option><option>Li</option><option>Na</option><option>Mg</option><option>Al</option><option>Si</option><option>K</option></select></label><div class="trendViz" data-trend-viz></div><output data-sim-output></output></section>`;
 return''
}
function fallbackMath(latex){return latex.replace(/\\qquad/g,' · ').replace(/\\Rightarrow/g,'⇒').replace(/\\rightarrow/g,'→').replace(/\\Delta/g,'Δ').replace(/\\nu/g,'ν').replace(/\\times/g,'×').replace(/[{}]/g,'')}
function mathNode(latex,display){const tag=display?'div':'span';return `<${tag} class="${display?'formulaBlock':'mathInline'}" data-latex="${encodeURIComponent(latex)}" data-display="${display}">${esc(fallbackMath(latex))}</${tag}>`}
function formatStudyHtml(raw){return String(raw||'').replace(/<p>\[([\s\S]*?)\]<\/p>/g,(_,m)=>mathNode(m,true)).replace(/\(([^<>]*?(?:\\[A-Za-z]+|\^[{+\-\dA-Za-z]|_[{A-Za-z\d])[^<>]*?)\)/g,(_,m)=>mathNode(m,false))}
function readableStudyHtml(s){const box=document.createElement('div');box.innerHTML=formatStudyHtml(s.html).replace(/spanclass/gi,'');box.querySelectorAll('p').forEach(p=>{const text=p.textContent.replace(/\s+/g,' ').trim();if(text.length<210||p.closest('li,td,th,details')||p.querySelector('strong,em,a,[data-latex]')){if(text.length>110)p.classList.add('airyText');return}const sentences=text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)?.map(x=>x.trim()).filter(Boolean)||[];if(sentences.length<2){p.classList.add('airyText');return}const chunk=document.createElement('div');chunk.className='memoryChunk';chunk.innerHTML=`<p><strong>${esc(sentences[0])}</strong></p><ul>${sentences.slice(1).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;p.replaceWith(chunk)});box.querySelectorAll('h2,h3,h4').forEach(h=>{if(!/ejemplo|resoluci.n|paso a paso|procedimiento|instructivo/i.test(h.textContent))return;const details=document.createElement('details');details.className='deferredRead';const summary=document.createElement('summary');summary.textContent=/ejemplo/i.test(h.textContent)?'Abrir ejemplo y resolución':'Abrir desarrollo paso a paso';details.append(summary);let next=h.nextSibling;while(next&&!/^H[234]$/.test(next.nodeName)){const current=next;next=next.nextSibling;details.append(current)}h.replaceWith(details)});return box.innerHTML}

function theorySupplement(s){
 if(unit===1&&/atomicidad/i.test(`${s.title} ${plain(s.html)}`))return `<aside class="theorySupplement"><h3>Atomicidad: definición precisa</h3><p>La <b>atomicidad</b> es la cantidad total de átomos que integran una molécula de una sustancia simple o compuesta. Se obtiene sumando los subíndices: O₂ es diatómica, O₃ triatómica y H₂O tiene atomicidad 3. <b>No se aplica del mismo modo a redes iónicas o metálicas</b>, porque no están formadas por moléculas discretas.</p></aside>`;
 if(unit===2&&/masa at.mica|uma|unidad de masa/i.test(`${s.title} ${plain(s.html)}`))return `<aside class="theorySupplement"><h3>Unidad de masa atómica, sin atajos</h3><ul><li><b>1 u</b> se define como la doceava parte de la masa de un átomo de carbono-12 neutro y en su estado fundamental.</li><li>Una masa isotópica compara la masa de un isótopo con ese patrón; no es el número másico A.</li><li>La masa atómica de la tabla es un <b>promedio ponderado</b>: Σ(masa isotópica × abundancia fraccionaria).</li><li>Numéricamente, la masa de una partícula en u coincide con la masa molar en g·mol⁻¹, pero son magnitudes diferentes.</li></ul><details class="deferredRead"><summary>Abrir ejemplo resuelto</summary><p>Si un elemento tiene 75 % de un isótopo de 35 u y 25 % de otro de 37 u: masa promedio = 35×0,75 + 37×0,25 = <b>35,5 u</b>.</p></details></aside>`;
 if(unit===2&&/cu.ntic|orbital/i.test(`${s.title} ${plain(s.html)}`))return `<aside class="theorySupplement"><h3>Los cuatro números cuánticos</h3><div class="quantumGrid"><div><b>n · nivel</b><p>1, 2, 3… Relaciona energía y extensión del orbital.</p></div><div><b>ℓ · subnivel</b><p>0 a n−1: s=0, p=1, d=2, f=3. Determina la forma.</p></div><div><b>mℓ · orientación</b><p>De −ℓ a +ℓ. Indica cuál orbital del subnivel: 1 s, 3 p, 5 d o 7 f.</p></div><div><b>ms · espín</b><p>+½ o −½. Distingue los dos electrones que puede contener un orbital.</p></div></div><ul><li><b>Pauli:</b> no existen dos electrones de un átomo con los cuatro números iguales.</li><li><b>Hund:</b> en orbitales degenerados se ocupan primero separados y con espines paralelos.</li><li><b>Aufbau:</b> se ocupan primero los orbitales de menor energía.</li></ul><details class="deferredRead"><summary>Relación con hibridación</summary><p>En enlace químico, orbitales atómicos de un mismo átomo pueden combinarse matemáticamente: sp produce dos direcciones lineales; sp², tres direcciones trigonales planas; sp³, cuatro direcciones tetraédricas. La hibridación usa orbitales compatibles y ayuda a describir geometrías, pero no cambia las reglas de Pauli y Hund.</p></details></aside>`;
 if(unit===2&&/propiedades peri.dicas|carga nuclear efectiva/i.test(`${s.title} ${plain(s.html)}`))return `<aside class="theorySupplement"><h3>Fundamento de las tendencias</h3><ul><li><b>A lo largo de un período:</b> aumenta Z, los electrones se agregan a la misma capa y el apantallamiento cambia poco. Aumenta Z<sub>ef</sub>, la atracción núcleo–electrón crece, el radio disminuye y suelen aumentar ionización y electronegatividad.</li><li><b>Al bajar en un grupo:</b> aparece una capa nueva, aumentan distancia y apantallamiento. El radio crece; suele disminuir la energía de ionización y la electronegatividad.</li><li><b>Repulsión electrónica:</b> los electrones se repelen y los internos apantallan parcialmente al núcleo; por eso un electrón externo no siente toda la carga Z.</li><li><b>Afinidad electrónica:</b> depende del balance entre atracción nuclear, tamaño, repulsión y estabilidad de configuraciones; presenta más excepciones que el radio.</li></ul></aside>`;
 return''
}
function renderMath(){document.querySelectorAll('[data-latex]').forEach(el=>{if(el.dataset.rendered||!window.katex)return;window.katex.render(decodeURIComponent(el.dataset.latex),el,{throwOnError:false,displayMode:el.dataset.display==='true',output:'htmlAndMathml'});el.dataset.rendered='true'})}
function simulatorWidget(s){const t=s.title.toLowerCase();if(t.includes('recipiente')||t.includes('gases'))return `<div class="simLab" data-sim="gas"><label>Moles <input type="range" min="1" max="10" value="2" step=".5" data-sim-input="n"></label><label>Temperatura (K) <input type="range" min="200" max="600" value="300" data-sim-input="t"></label><label>Volumen (L) <input type="range" min="2" max="30" value="10" data-sim-input="v"></label><output>Presión: <b data-sim-output></b></output></div>`;if(t.includes('dilución'))return `<div class="simLab" data-sim="dilution"><label>C₁ (M) <input type="number" value="1" step=".1" data-sim-input="c1"></label><label>V₁ (mL) <input type="number" value="100" data-sim-input="v1"></label><label>V₂ (mL) <input type="number" value="500" data-sim-input="v2"></label><output>C₂: <b data-sim-output></b></output></div>`;if(t.includes('pH')||t.includes('ácido'))return `<div class="simLab" data-sim="ph"><label>Tipo <select data-sim-input="kind"><option value="acid">Ácido fuerte</option><option value="base">Base fuerte</option></select></label><label>Concentración (M) <input type="number" value="0.01" min="0.0000001" step=".001" data-sim-input="c"></label><output>pH: <b data-sim-output></b></output></div>`;if(t.includes('choques')||t.includes('velocidad'))return `<div class="simLab" data-sim="rate"><label>Concentración relativa <input type="range" min="1" max="5" value="1" data-sim-input="c"></label><label>Temperatura relativa <input type="range" min="1" max="4" value="1" data-sim-input="t"></label><output>Choques eficaces relativos: <b data-sim-output></b></output></div>`;return ''}
function updateSimulator(lab){const val=k=>Number(lab.querySelector(`[data-sim-input="${k}"]`)?.value||0),out=lab.querySelector('[data-sim-output]');if(!out)return;if(lab.dataset.sim==='gas')out.textContent=`${(val('n')*.082057*val('t')/val('v')).toFixed(2)} atm`;if(lab.dataset.sim==='dilution')out.textContent=`${(val('c1')*val('v1')/val('v2')).toFixed(3)} M`;if(lab.dataset.sim==='rate')out.textContent=`${(val('c')**2*val('t')).toFixed(1)}×`;if(lab.dataset.sim==='ph'){const c=Math.max(val('c'),1e-14),kind=lab.querySelector('[data-sim-input="kind"]').value;out.textContent=(kind==='acid'?-Math.log10(c):14+Math.log10(c)).toFixed(2)}}
function drawParticles(lab,state='solid'){
  const svg=lab.querySelector('.particleStage');if(!svg)return;const temp=Number(lab.querySelector('[data-sim-input="temp"]')?.value||15),count=state==='gas'?18:state==='liquid'?34:40,points=[];
  for(let i=0;i<count;i++){let x,y;if(state==='solid'){x=105+(i%8)*42;y=36+Math.floor(i/8)*39}else if(state==='liquid'){x=42+(i%9)*52+(i%2)*8;y=92+Math.floor(i/9)*35}else{x=28+((i*83)%460);y=24+((i*59)%180)}points.push(`<circle cx="${x}" cy="${y}" r="9" style="--dx:${((i%5)-2)*(2+temp/15)}px;--dy:${((i%7)-3)*(2+temp/18)}px;animation-duration:${Math.max(.35,2-temp/70)}s"/>`)}
  svg.innerHTML=`<rect x="8" y="8" width="504" height="214" rx="18"/>${points.join('')}`;lab.dataset.state=state;lab.querySelectorAll('[data-state]').forEach(b=>b.classList.toggle('active',b.dataset.state===state));lab.querySelector('[data-sim-output]').textContent=state==='solid'?'Partículas próximas, ordenadas y vibrando en posiciones fijas.':state==='liquid'?'Partículas próximas que se deslizan y cambian de vecinas.':'Partículas muy separadas, rápidas y con choques frecuentes.'
}
function initMatterCanvas(lab){const canvas=lab.querySelector('[data-matter-canvas]');if(!canvas||canvas.dataset.ready)return;canvas.dataset.ready='true';const ctx=canvas.getContext('2d'),particles=[];let collisions=0,last=performance.now();const resize=()=>{const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=Math.max(1,r.width*d);canvas.height=Math.max(1,r.height*d);ctx.setTransform(d,0,0,d,0,0);reset()};const reset=()=>{particles.length=0;const state=lab.dataset.state||'solid',w=canvas.clientWidth,h=canvas.clientHeight,count=state==='gas'?25:state==='liquid'?38:42;for(let i=0;i<count;i++){const col=i%7,row=Math.floor(i/7),a=Math.random()*Math.PI*2;particles.push({x:state==='solid'?40+col*Math.max(30,(w-80)/6):25+Math.random()*(w-50),y:state==='solid'?48+row*34:state==='liquid'?h*.42+Math.random()*(h*.48):25+Math.random()*(h-50),homeX:40+col*Math.max(30,(w-80)/6),homeY:48+row*34,vx:Math.cos(a)*(45+Math.random()*35),vy:Math.sin(a)*(45+Math.random()*35),r:7})}collisions=0};lab._matterReset=reset;const step=now=>{if(!canvas.isConnected)return;const dt=Math.min(.032,(now-last)/1000);last=now;const w=canvas.clientWidth,h=canvas.clientHeight,temp=Number(lab.querySelector('[data-sim-input="temp"]')?.value||15),state=lab.dataset.state||'solid',speed=.45+temp/55;ctx.clearRect(0,0,w,h);ctx.fillStyle='rgba(15,159,154,.045)';ctx.strokeStyle='rgba(15,159,154,.45)';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(8,8,w-16,h-16,18);ctx.fill();ctx.stroke();for(const p of particles){if(state==='solid'){p.x=p.homeX+Math.sin(now/90+p.homeY)*Math.min(7,1+temp/18);p.y=p.homeY+Math.cos(now/105+p.homeX)*Math.min(7,1+temp/18)}else{p.x+=p.vx*speed*dt;p.y+=p.vy*speed*dt;const top=state==='liquid'?h*.38:16;if(p.x-p.r<16||p.x+p.r>w-16){p.vx*=-1;collisions++}if(p.y-p.r<top||p.y+p.r>h-16){p.vy*=-1;collisions++}p.x=Math.max(16+p.r,Math.min(w-16-p.r,p.x));p.y=Math.max(top+p.r,Math.min(h-16-p.r,p.y))}const g=ctx.createRadialGradient(p.x-2,p.y-2,1,p.x,p.y,p.r*1.8);g.addColorStop(0,'#bdf8f3');g.addColorStop(1,state==='gas'?'#0f9f9a':state==='liquid'?'#087f91':'#245d7a');ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}lab.querySelector('[data-matter-collisions]').textContent=String(collisions);requestAnimationFrame(step)};new ResizeObserver(resize).observe(canvas);resize();requestAnimationFrame(step)}
function setMatterState(lab,state){lab.dataset.state=state;lab.querySelectorAll('[data-state]').forEach(b=>b.classList.toggle('active',b.dataset.state===state));const labels={solid:['Sólido','vibración en posiciones fijas'],liquid:['Líquido','deslizamiento entre partículas'],gas:['Gas','traslación rápida y libre']};lab.querySelector('[data-matter-state]').textContent=labels[state][0];lab.querySelector('[data-matter-speed]').textContent=labels[state][1];lab._matterReset?.();lab.querySelector('[data-sim-output]').textContent=state==='solid'?'Muy próximas, ordenadas y con movimiento de vibración.':state==='liquid'?'Próximas, desordenadas y capaces de cambiar de vecinas.':'Muy separadas, rápidas y con choques contra las paredes.'}
function updateStudySimulator(lab){const out=lab.querySelector('[data-sim-output]');if(lab.dataset.sim==='states'){initMatterCanvas(lab);if(!lab.dataset.state)setMatterState(lab,'solid');return}if(lab.dataset.sim==='density'){const m=Number(lab.querySelector('[data-sim-input="mass"]').value),v=Number(lab.querySelector('[data-sim-input="volume"]').value),rho=m/v;lab.querySelector('[data-level]').style.height=`${Math.max(12,Math.min(92,v/2))}%`;lab.querySelector('[data-mass]').textContent=`${m} g`;out.innerHTML=`ρ = ${m} g ÷ ${v} mL = <b>${rho.toFixed(2)} g/mL</b> · ${rho>1?'Se hundiría en agua.':'Flotaría en agua.'}`;return}if(lab.dataset.sim==='atom'){const p=Number(lab.querySelector('[data-sim-input="p"]').value),n=Number(lab.querySelector('[data-sim-input="n"]').value),e=Number(lab.querySelector('[data-sim-input="e"]').value),symbols=['','H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca'],q=p-e,A=p+n,charge=q===0?'':`${Math.abs(q)>1?Math.abs(q):''}${q>0?'+':'−'}`;lab.querySelector('[data-atom-nucleus]').textContent=`${p}p · ${n}n`;out.innerHTML=`<b>${A}${symbols[p]}${charge}</b> · Z=${p} · A=${A} · ${e} electrones · ${q===0?'átomo neutro':q>0?'catión':'anión'}`;return}if(lab.dataset.sim==='configuration'){const z=Number(lab.querySelector('[data-sim-input="z"]').value),element=periodicElements.find(x=>x.z===z)||{name:['','Hidrógeno','Helio','Litio','Berilio','Boro','Carbono','Nitrógeno','Oxígeno','Flúor','Neón','Sodio','Magnesio','Aluminio','Silicio','Fósforo','Azufre','Cloro','Argón','Potasio','Calcio'][z],symbol:['','H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca'][z]};lab.querySelector('[data-z-label]').textContent=z;let left=z,parts=[],boxes=[],levels=[['1s',2],['2s',2],['2p',6],['3s',2],['3p',6],['4s',2]];for(const [name,cap] of levels){if(left<=0)break;const take=Math.min(left,cap);parts.push(`${name}${'⁰¹²³⁴⁵⁶'[take]}`);boxes.push(`<span><b>${name}</b>${Array.from({length:cap/2},(_,i)=>`<i>${i<take?'↑':''}${i+cap/2<take?'↓':''}</i>`).join('')}</span>`);left-=take}lab.querySelector('[data-electron-boxes]').innerHTML=boxes.join('');out.innerHTML=`<b>Z = ${z} · ${element.name} (${element.symbol})</b><br>Configuración: <b>${parts.join(' ')}</b>`;return}if(lab.dataset.sim==='trends'){const data={Li:[2,1,152,.98],Na:[3,1,186,.93],Mg:[3,2,160,1.31],Al:[3,13,143,1.61],Si:[3,14,118,1.90],Cl:[3,17,99,3.16],K:[4,1,227,.82]},a=lab.querySelector('[data-sim-input="a"]').value,b=lab.querySelector('[data-sim-input="b"]').value,A=data[a],B=data[b];out.innerHTML=`<b>Radio:</b> ${A[2]>B[2]?a:b} es mayor (${A[2]} vs ${B[2]} pm). <b>Electronegatividad:</b> ${A[3]>B[3]?a:b} es mayor (${A[3]} vs ${B[3]}).`;return}}
function initSectionTracking(){const buttons=[...document.querySelectorAll('.unitToc [data-scroll]')],sections=[...document.querySelectorAll('[data-section]')];if(!buttons.length||!sections.length||!('IntersectionObserver'in window))return;const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;buttons.forEach(b=>b.classList.toggle('active',b.dataset.scroll===visible.target.dataset.section))},{rootMargin:'-18% 0px -65% 0px',threshold:[0,.2,.6]});sections.forEach(s=>observer.observe(s))}
const STUDY_CARDS={
  1:[
    ['¿Masa y peso significan lo mismo?','No. La masa mide cantidad de materia e inercia; el peso es una fuerza gravitatoria y depende del lugar.'],
    ['¿Por qué un gas es mucho más compresible que un líquido?','Porque sus partículas están muy separadas y existe mucho espacio vacío entre ellas.'],
    ['¿Qué cambia durante una fusión?','Cambia el estado y la organización de las partículas; la identidad química de la sustancia se conserva.'],
    ['¿Evaporación y ebullición son iguales?','No. La evaporación ocurre en la superficie y a distintas temperaturas; la ebullición ocurre en toda la masa al alcanzar el punto de ebullición.'],
    ['Si corto un bloque por la mitad, ¿cambia su densidad?','No, si el material y las condiciones se mantienen. Masa y volumen disminuyen proporcionalmente: la densidad es intensiva.'],
    ['¿Puede un sistema tener dos fases y un solo componente?','Sí. Hielo y agua líquida forman dos fases, pero ambas son H₂O: hay un componente.'],
    ['¿Puede una mezcla de dos componentes ser homogénea?','Sí. Sal completamente disuelta en agua tiene una fase y dos componentes.'],
    ['¿Por qué NaCl no se describe como una molécula aislada?','Porque en estado sólido forma una red iónica. Se habla de unidad fórmula, no de molécula de NaCl.'],
    ['¿Qué método usarías para separar arena de agua?','Filtración: el líquido atraviesa el filtro y la arena insoluble queda retenida.'],
    ['¿Qué método permite separar pigmentos de una tinta?','Cromatografía, aprovechando su diferente afinidad por la fase móvil y la fase estacionaria.'],
    ['¿Qué significa 20 % m/m de glucosa?','Que hay 20 g de glucosa por cada 100 g de solución. Los 80 g restantes corresponden a los demás componentes.'],
    ['¿Qué control final conviene hacer en una composición porcentual?','Comprobar unidades y verificar que los porcentajes sumen aproximadamente 100 %.']
  ],
  2:[
    ['¿Qué determina la identidad de un elemento?','El número atómico Z, es decir, su cantidad de protones.'],
    ['¿Cómo se calcula el número de neutrones?','n = A − Z, porque el número másico A es protones más neutrones.'],
    ['¿Cómo se calcula la carga de una especie?','q = protones − electrones. Si faltan electrones, la carga es positiva; si sobran, es negativa.'],
    ['¿Qué cambia cuando un átomo forma un ion?','Cambia la cantidad de electrones. El núcleo, Z y la identidad del elemento no cambian.'],
    ['¿Qué tienen en común dos isótopos?','El mismo Z y, por lo tanto, el mismo elemento; difieren en A porque tienen distinta cantidad de neutrones.'],
    ['¿Qué significa que dos especies sean isoelectrónicas?','Que poseen la misma cantidad total de electrones, aunque sus núcleos y tamaños puedan ser distintos.'],
    ['¿Por qué la masa atómica de la tabla suele tener decimales?','Porque es un promedio ponderado de las masas de los isótopos naturales según sus abundancias.'],
    ['¿Qué evidencia llevó al modelo nuclear de Rutherford?','Las grandes desviaciones de unas pocas partículas alfa al atravesar una lámina de oro.'],
    ['¿Qué aporta Bohr que Rutherford no explicaba?','Niveles de energía cuantizados capaces de explicar estabilidad y líneas espectrales del hidrógeno.'],
    ['¿Un orbital es una órbita?','No. Un orbital es una región de alta probabilidad de encontrar al electrón; no es una trayectoria definida.'],
    ['¿Cuántos electrones admite un orbital?','Como máximo dos, con espines opuestos, según el principio de exclusión de Pauli.'],
    ['¿Qué indica la regla de Hund?','En orbitales de igual energía, los electrones se ubican primero separados y con espines paralelos antes de aparearse.'],
    ['¿Por qué suele disminuir el radio atómico de izquierda a derecha?','Porque aumenta la cantidad de protones mientras los electrones se agregan a la misma capa. El apantallamiento no compensa ese aumento: crece la carga nuclear efectiva y la nube se contrae.'],
    ['¿Por qué la electronegatividad suele aumentar hacia la derecha y hacia arriba?','Hacia la derecha aumenta la carga nuclear efectiva; hacia arriba hay menos capas y menor apantallamiento. En ambos casos el núcleo atrae con más fuerza a los electrones compartidos. Es una tendencia general, no una regla sin excepciones.']
  ]
};
updateStudySimulator=updateStudySimulatorV2;
function updateStudySimulatorV2(lab){
 const out=lab.querySelector('[data-sim-output]'),num=k=>Number(lab.querySelector(`[data-sim-input="${k}"]`)?.value||0);
 if(lab.dataset.sim==='states'){initMatterCanvas(lab);if(!lab.dataset.state)setMatterState(lab,'solid');return}
 if(lab.dataset.sim==='density'){const m=num('mass'),v=num('volume'),rho=m/v;lab.querySelector('[data-level]').style.height=`${Math.max(12,Math.min(92,v/2))}%`;lab.querySelector('[data-mass]').textContent=`${m} g`;out.innerHTML=`ρ = ${m} g ÷ ${v} mL = <b>${rho.toFixed(2)} g/mL</b> · ${rho>1?'Se hundiría en agua.':'Flotaría en agua.'}`;return}
 if(lab.dataset.sim==='concentration'){const solute=num('solute'),total=Math.max(solute,num('total')),type=lab.dataset.concentrationType||'mm',value=solute/total*100;lab.querySelector('[data-solute-label]').innerHTML=`Masa de soluto: <b>${solute} g</b>`;lab.querySelector('[data-total-label]').innerHTML=type==='mm'?`Masa de solución: <b>${total} g</b>`:`Volumen de solución: <b>${total} mL</b>`;lab.querySelector('[data-concentration-fill]').style.height=`${Math.min(92,25+total/4)}%`;lab.querySelector('[data-concentration-dots]').style.opacity=String(Math.min(.95,.18+value/70));lab.querySelector('[data-concentration-value]').textContent=`${value.toFixed(1)} % ${type==='mm'?'m/m':'m/V'}`;out.innerHTML=type==='mm'?`<b>${solute} g de soluto cada ${total} g de solución.</b> El denominador es una masa.`:`<b>${solute} g de soluto cada ${total} mL de solución.</b> El denominador es un volumen.`;return}
 if(lab.dataset.sim==='atom'){const p=num('p'),n=num('n'),e=num('e'),elements=['','Hidrógeno','Helio','Litio','Berilio','Boro','Carbono','Nitrógeno','Oxígeno','Flúor','Neón','Sodio','Magnesio','Aluminio','Silicio','Fósforo','Azufre','Cloro','Argón','Potasio','Calcio'],symbols=['','H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca'],q=p-e,A=p+n,charge=q===0?'':`${Math.abs(q)>1?Math.abs(q):''}${q>0?'+':'−'}`;lab.querySelector('[data-p-label]').textContent=p;lab.querySelector('[data-n-label]').textContent=n;lab.querySelector('[data-e-label]').textContent=e;lab.querySelector('[data-count-p]').textContent=p;lab.querySelector('[data-count-n]').textContent=n;lab.querySelector('[data-count-e]').textContent=e;lab.querySelector('[data-atom-nucleus]').innerHTML=`<b>${p}p⁺</b><b>${n}n⁰</b>`;const cloud=lab.querySelector('[data-electron-cloud]');cloud.innerHTML=Array.from({length:e},(_,i)=>`<i style="--i:${i};--x:${12+((i*47)%76)}%;--y:${10+((i*67)%80)}%;--d:${1.8+(i%5)*.37}s"></i>`).join('');out.innerHTML=`<b><sup>${A}</sup><sub>${p}</sub>${symbols[p]}${charge} · ${elements[p]}</b><br>Z=${p} · A=${A} · ${e} e⁻ · ${q===0?'átomo neutro':q>0?'catión':'anión'} · distribución por capas: ${[2,8,8,2].reduce((r,cap)=>{const used=Math.min(r.left,cap);r.parts.push(used);r.left-=used;return r},{left:e,parts:[]}).parts.join('–')}`;return}
 if(lab.dataset.sim==='configuration'){const z=num('z'),element=periodicElements.find(x=>Number(x.z)===z)||{name:['','Hidrógeno','Helio','Litio','Berilio','Boro','Carbono','Nitrógeno','Oxígeno','Flúor','Neón','Sodio','Magnesio','Aluminio','Silicio','Fósforo','Azufre','Cloro','Argón','Potasio','Calcio'][z],symbol:['','H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca'][z]};lab.querySelector('[data-z-label]').textContent=z;let left=z,parts=[],boxes=[],levels=[['1s',2],['2s',2],['2p',6],['3s',2],['3p',6],['4s',2]];for(const [name,cap] of levels){if(left<=0)break;const take=Math.min(left,cap);parts.push(`${name}<sup>${take}</sup>`);boxes.push(`<span><b>${name}</b>${Array.from({length:cap/2},(_,i)=>`<i>${i<take?'↑':''}${i+cap/2<take?'↓':''}</i>`).join('')}</span>`);left-=take}lab.querySelector('[data-electron-boxes]').innerHTML=boxes.join('');out.innerHTML=`<b>Z = ${z} · ${element.name} (${element.symbol})</b><br>Configuración: <b>${parts.join(' ')}</b>`;return}
 if(lab.dataset.sim==='trends'){const data={Li:[2,3,152,.98,1.3],Na:[3,11,186,.93,2.2],Mg:[3,12,160,1.31,2.85],Al:[3,13,143,1.61,3.5],Si:[3,14,118,1.90,4.15],Cl:[3,17,99,3.16,6.1],K:[4,19,227,.82,2.2]},a=lab.querySelector('[data-sim-input="a"]').value,b=lab.querySelector('[data-sim-input="b"]').value,A=data[a],B=data[b],viz=lab.querySelector('[data-trend-viz]');viz.innerHTML=[[a,A],[b,B]].map(([name,d])=>`<div><b>${name}</b><span>capas ${d[0]}</span><i style="width:${d[2]/2.4}px;height:${d[2]/2.4}px"></i><small>Z<sub>ef</sub> aprox. ${d[4]}</small></div>`).join('');out.innerHTML=`<b>Radio:</b> ${A[2]>B[2]?a:b} es mayor porque predominan distancia y apantallamiento. <b>Electronegatividad:</b> ${A[3]>B[3]?a:b} es mayor porque atrae con más intensidad a los electrones de enlace. Comparación: ${A[2]} vs ${B[2]} pm; χ ${A[3]} vs ${B[3]}.`;return}
}
function studyDeck(){const cards=STUDY_CARDS[unit];if(!cards)return'';return `<section id="sec-flashcards" class="studyDeck" data-section="flashcards" data-deck-unit="${unit}"><header><div><span>TARJETAS DE ESTUDIO</span><h2>Preguntá, pensá, girá</h2><p>Intentá responder antes de dar vuelta la tarjeta. Usá las flechas o el teclado para avanzar.</p></div><div class="deckScore"><b data-deck-seen>0</b><small>vistas de ${cards.length}</small></div></header><div class="deckStage"><article class="flashcard" role="button" tabindex="0" aria-label="Dar vuelta tarjeta" aria-pressed="false"><div class="flashcardInner"><div class="cardFace cardFront"><span>PREGUNTA</span><h3 data-card-question></h3><small>Tocá para ver la respuesta ↻</small></div><div class="cardFace cardBack"><span>RESPUESTA</span><p data-card-answer></p><small>Tocá para volver ↻</small></div></div></article></div><footer><button class="secondary" data-deck-prev aria-label="Tarjeta anterior">← Anterior</button><button class="ghost" data-deck-shuffle>⇄ Barajar</button><span data-deck-progress>1 / ${cards.length}</span><button class="secondary" data-deck-next aria-label="Tarjeta siguiente">Siguiente →</button></footer></section>`}
function initStudyDeck(){const deck=document.querySelector('.studyDeck');if(!deck)return;let cards=[...STUDY_CARDS[Number(deck.dataset.deckUnit)]],index=0;const seen=new Set(),card=deck.querySelector('.flashcard'),q=deck.querySelector('[data-card-question]'),a=deck.querySelector('[data-card-answer]'),progress=deck.querySelector('[data-deck-progress]'),seenLabel=deck.querySelector('[data-deck-seen]');const show=()=>{card.classList.remove('flipped');card.setAttribute('aria-pressed','false');q.textContent=cards[index][0];a.textContent=cards[index][1];progress.textContent=`${index+1} / ${cards.length}`};const flip=()=>{card.classList.toggle('flipped');card.setAttribute('aria-pressed',String(card.classList.contains('flipped')));seen.add(cards[index][0]);seenLabel.textContent=seen.size};const move=step=>{index=(index+step+cards.length)%cards.length;show()};card.onclick=flip;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();flip()}if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)};deck.querySelector('[data-deck-prev]').onclick=()=>move(-1);deck.querySelector('[data-deck-next]').onclick=()=>move(1);deck.querySelector('[data-deck-shuffle]').onclick=()=>{for(let i=cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}index=0;show()};show()}
function reviewStrip(){const items=unit===2?['¿Leés Z, A y carga sin confundirlos?','¿Escribís configuraciones controlando electrones?','¿Justificás tendencias con capas y carga nuclear efectiva?']:['¿Podés distinguir fase de componente?','¿Justificás un método de separación?','¿Controlás unidades y porcentajes?'];return `<section id="sec-repaso" class="reviewStrip" data-section="repaso"><span>CIERRE</span><h2>Antes de terminar</h2><div>${items.map(x=>`<p>✓ ${x}</p>`).join('')}</div></section>`}
function mentalMap(sections){return `<section id="sec-mental-map" class="mentalMap" data-section="mental-map"><span>MAPA MENTAL</span><h2>La unidad en una mirada</h2><div class="mindRoot"><strong>Unidad ${unit}</strong>${sections.map((s,i)=>`<button data-scroll="${s.key}" style="--branch:${i}">${esc(s.title.replace(/^\d+\.\s*/,''))}</button>`).join('')}</div></section>`}
const hiddenSection=s=>/lectura interactiva|a darle .tomos|errores frecuentes|indispensables? para el parcial/i.test(`${s.key} ${s.title}`)||(unit===2&&(/del .tomo indivisible al modelo orbital/i.test(s.title)||/^cap-?0?[56]$/i.test(s.key)));
const HISTORY_EVENTS=[
  {year:'c. 450 a. C.',pos:0,name:'Demócrito y Leucipo',model:'La idea de átomo',lead:'Propusieron que la materia podía dividirse hasta llegar a partículas indivisibles llamadas átomos.',why:'Fue una idea filosófica, no una teoría experimental. Su valor está en haber formulado la pregunta: ¿la materia es continua o está hecha de unidades?',limit:'No había mediciones ni un modelo capaz de predecir resultados.'},
  {year:'1803–1808',pos:8,name:'John Dalton',model:'Esfera maciza',lead:'Convirtió la antigua idea en una teoría vinculada con las leyes de combinación química.',why:'Los átomos de un elemento se consideraban iguales y los compuestos se formaban en proporciones enteras simples. Así se entendían la conservación de la masa y las proporciones definidas.',limit:'El átomo no es indivisible y existen isótopos.',image:'./assets/chemistry/unit-02/atomic-models.svg'},
  {year:'1897–1904',pos:58,name:'J. J. Thomson',model:'Carga positiva con electrones',lead:'El descubrimiento del electrón mostró que el átomo tenía estructura interna.',why:'Los rayos catódicos se desviaban por campos eléctricos y magnéticos. Thomson propuso electrones negativos incrustados en una región de carga positiva.',limit:'No explica la concentración de masa y carga positiva en un núcleo.',image:'./assets/chemistry/history/jj-thomson.jpg',credit:'J. J. Thomson · The Electrician (1896) · dominio público'},
  {year:'1909–1911',pos:67,name:'Geiger, Marsden y Rutherford',model:'Modelo nuclear',lead:'La lámina de oro reveló que el átomo es casi todo espacio vacío y posee un núcleo pequeño, masivo y positivo.',why:'La mayoría de las partículas alfa atravesó la lámina; unas pocas se desviaron mucho. Una carga positiva difusa no podía producir esas grandes desviaciones.',limit:'El modelo clásico no explicaba por qué los electrones no caían al núcleo ni los espectros de líneas.',image:'./assets/chemistry/history/ernest-rutherford.jpg',credit:'Ernest Rutherford · Library of Congress · sin restricciones conocidas',extra:'./assets/chemistry/unit-02/rutherford-experiment-wikimedia.svg'},
  {year:'1913',pos:69,name:'Niels Bohr',model:'Niveles cuantizados',lead:'Los electrones sólo pueden ocupar ciertos niveles de energía y emitir o absorber energía al cambiar entre ellos.',why:'Explica con gran precisión el espectro del hidrógeno: cada línea corresponde a una diferencia de energía permitida.',limit:'Funciona muy bien para hidrógeno y especies con un electrón, pero no describe por completo átomos multielectrónicos.',image:'./assets/chemistry/history/niels-bohr.jpg',credit:'Niels Bohr · fotografía histórica · dominio público',extra:'./assets/chemistry/unit-02/hydrogen-spectrum-wikimedia.png'},
  {year:'1924',pos:75,name:'Louis de Broglie',model:'Materia con comportamiento ondulatorio',lead:'Propuso que un electrón también puede asociarse con una longitud de onda.',why:'Esta dualidad onda-partícula abrió el camino para reemplazar las órbitas definidas por estados ondulatorios.',limit:'La propuesta necesitaba una formulación matemática general y comprobaciones experimentales.'},
  {year:'1926–1927',pos:77,name:'Schrödinger, Born y Heisenberg',model:'Modelo mecánico-cuántico',lead:'El electrón deja de describirse como una bolita en una trayectoria: se representa mediante estados y probabilidades.',why:'La función de onda permite calcular distribuciones de probabilidad. Los orbitales son regiones asociadas a una alta probabilidad de encontrar al electrón; el principio de incertidumbre limita conocer simultáneamente posición y cantidad de movimiento con precisión arbitraria.',limit:'No ofrece trayectorias intuitivas: exige pensar en probabilidades, números cuánticos y mediciones.',image:'./assets/chemistry/unit-02/orbital-clouds-wikimedia.png',credit:'Nubes orbitales · Geek3 · CC BY-SA 4.0'},
  {year:'Actualidad',pos:100,name:'El modelo que usamos hoy',model:'Orbitales y estructura electrónica',lead:'La química general usa el modelo cuántico para organizar configuraciones electrónicas y explicar periodicidad y enlace.',why:'No “vemos” un orbital como un objeto sólido: es una representación de un estado electrónico. Su poder está en conectar cálculos con espectros, energías y comportamiento químico.',limit:'Todo modelo tiene alcance. Para núcleos, relatividad o sistemas complejos se necesitan teorías y aproximaciones adicionales.'}
];
function historyPage(){const source=sectionsByUnit[2]?.find(s=>s.key==='1-del-atomo-indivisible-al-modelo-orbital');return `<section class="historyHero"><span class="eyebrow">UNIDAD ESPECIAL · HISTORIA</span><h1>Cómo cambió nuestra idea del átomo</h1><p>Una línea de tiempo para seguir la evidencia: cada modelo aparece porque el anterior dejó una pregunta sin responder.</p><div class="historyScale"><span>1800</span><span>1850</span><span>1900</span><span>1925</span><span>Hoy</span>${HISTORY_EVENTS.slice(1).map(e=>`<i style="--x:${e.pos}%" title="${e.year} · ${e.name}"></i>`).join('')}</div><small>Escala temporal aproximada desde 1800. La etapa filosófica antigua se presenta aparte por el gran salto cronológico.</small></section><section class="ancientStop"><b>c. 450 a. C.</b><div><h2>Antes de los experimentos</h2><p>Demócrito y Leucipo imaginaron unidades indivisibles. Pasarían más de dos mil años hasta que Dalton relacionara esa idea con mediciones químicas.</p></div></section><div class="historyTimeline">${HISTORY_EVENTS.slice(1).map((e,i)=>`<article class="historyEvent" style="--timeline-x:${e.pos}"><div class="historyYear">${e.year}</div><div class="historyDot" aria-hidden="true"></div><section><header><span>${e.model}</span><h2>${e.name}</h2><p>${e.lead}</p></header>${e.image?`<figure><img loading="lazy" src="${e.image}" alt="${e.name}: ${e.model}">${e.credit?`<figcaption>${e.credit}</figcaption>`:''}</figure>`:''}${e.extra?`<figure class="historyExtra"><img loading="lazy" src="${e.extra}" alt="Evidencia vinculada con ${e.name}"></figure>`:''}<details open><summary>Qué evidencia explica</summary><p>${e.why}</p></details><details><summary>Modelo: qué propone</summary><p><b>${e.model}.</b> ${e.lead}</p></details><details><summary>Qué no podía explicar todavía</summary><p>${e.limit}</p></details></section></article>`).join('')}</div><details class="historyLongRead"><summary>Desarrollo histórico completo</summary><div>${source?formatStudyHtml(source.html):HISTORY_EVENTS.map(e=>`<h2>${e.year} · ${e.name}</h2><p>${e.lead} ${e.why}</p><p><strong>Límite del modelo:</strong> ${e.limit}</p>`).join('')}</div></details>`}
function unitPage(){if(!canUnit(unit))return `<section class="lockedPage"><div class="bigIcon">🔒</div><span class="eyebrow">Unidad ${unit}</span><h1>Esta unidad no está habilitada.</h1><p>El acceso se asigna por unidad, capítulo o evaluación y puede vencer en una fecha determinada.</p></section>`;const sections=(sectionsByUnit[unit]||[]).filter(s=>canSection(unit,s));const exercises=exercisesByUnit[unit]||[];if(!sections.length&&!exercises.length)return `<section class="hero"><span class="eyebrow">Química · Unidad ${unit}</span><h1>${UNIT_TITLES[unit]||`Unidad ${unit}`}</h1><p>La estructura está lista; el contenido se incorporará más adelante.</p></section>`;const u1=unit===1,premium=unit===1||unit===2,navSections=sections.filter(s=>s.key!=='intro'&&s.key!=='preguntas-de-comprobacion'&&!(unit===2&&s.key==='1-del-atomo-indivisible-al-modelo-orbital'));return `<section class="unitHero ${premium?'masterHero':''}"><span class="eyebrow">Química CBC</span><span class="unitNumber">Unidad ${unit}</span><h1>${UNIT_TITLES[unit]||`Unidad ${unit}`}</h1><p>${u1?'Materia, propiedades y transformaciones explicadas desde lo observable hasta el modelo de partículas.':unit===2?'Del núcleo a la tabla periódica: modelos, configuraciones y tendencias para entender el comportamiento químico.':'Teoría, ejemplos y práctica organizados para estudiar con claridad.'}</p>${premium?'<div class="heroMotif" aria-hidden="true">⚛</div>':''}<div class="unitStats"><span>${sections.length} secciones</span><span>${exercises.length} ejercicios</span></div></section><button class="mobileTocButton" data-a="toggleToc" aria-expanded="${tocOpen}">☰ Contenido de la unidad</button><div class="studyLayout"><nav class="unitToc ${tocOpen?'open':''}" aria-label="Índice de la unidad"><b>Contenido de la unidad</b><div>${navSections.map((s,i)=>`<button data-scroll="${s.key}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title.replace(/^\d+\.\s*/,''))}</button>`).join('')}<button data-scroll="flashcards"><span>★</span>Tarjetas de estudio</button>${exercises.length?'<button data-scroll="exercises"><span>PR</span>Ejercicios</button>':''}<button data-scroll="repaso"><span>✓</span>Repaso</button></div></nav><div class="studyFlow">${premium?`<section id="sec-map" class="unitMap"><div><span class="eyebrow">Mapa de la unidad</span><h2>${u1?'De la materia a su composición':'Del núcleo a la periodicidad'}</h2><p>${u1?'Observamos propiedades, construimos modelos, clasificamos sistemas y terminamos calculando cuánto aporta cada componente.':'Identificamos partículas, describimos orbitales, distribuimos electrones y usamos la tabla para predecir propiedades.'}</p></div><div class="mapSteps"><span>Observar</span><b>→</b><span>Modelar</span><b>→</b><span>Clasificar</span><b>→</b><span>Calcular</span></div></section>`:''}<div class="studySections">${navSections.map((s,i)=>`<section id="sec-${s.key}" class="studySection ${s.type}" data-section="${s.key}"><header><small>${sectionLabel(s.type)} · ${String(i+1).padStart(2,'0')}</small><h2>${esc(s.title.replace(/^\d+\.\s*/,''))}</h2></header><article>${unitVisual(s)}${quickGuide(s)}${readableStudyHtml(s)}${/simulador|calculadora/i.test(s.title)?simulatorWidget(s):''}${studySimulator(s)}</article></section>`).join('')}</div>${studyDeck()}${exercises.length?`<section id="sec-exercises" class="exerciseBook" data-section="exercises"><div class="sectionHeading"><span>PRÁCTICA · 08</span><h2>Ejercicios</h2><p>Intentá cada consigna antes de abrir la respuesta. Si no está habilitada para tu cuenta, el botón no aparece.</p></div>${exercises.map(exerciseCard).join('')}</section>`:''}${reviewStrip()}</div></div>`}
