function expiryLabel(u){if(!u.active)return'Suspendido';if(!u.access_expires_at)return'Sin vencimiento';const d=new Date(u.access_expires_at);if(d<Date.now())return'Vencido';return`Vence ${fmtDate(d)}`}
function grantSummary(email){const gs=userGrants(email);if(!gs.length)return'Sin permisos privados';const by=[...new Set(gs.map(g=>`U${g.unit_no}`))];return by.join(' · ')}
function unitGrantCard(u){const full=hasDraftFull(u),sections=sectionsByUnit[u]||[],chapters=sections.filter(s=>s.type==='chapter'),others=sections.filter(s=>s.type!=='chapter').slice(0,20);return `<div class="grantUnit"><div class="grantUnitHead"><div><span>Unidad ${u}</span>${u===1?'<small>Pública para invitados</small>':''}</div><label class="checkRow"><input type="checkbox" data-full-unit="${u}" ${full?'checked':''}> Toda la unidad</label></div>${chapters.length?`<div class="grantSub"><b>Capítulos</b>${chapters.map(s=>`<label class="checkRow"><input type="checkbox" data-grant-section="${u}|chapter|${s.key}" ${hasDraftSection(u,'chapter',s.key)?'checked':''} ${full?'disabled':''}> ${esc(s.title.replace(/^\d+\.\s*/,''))}</label>`).join('')}</div>`:''}${others.length?`<div class="grantSub"><b>Secciones</b>${others.map(s=>`<label class="checkRow"><input type="checkbox" data-grant-section="${u}|${s.type}|${s.key}" ${hasDraftSection(u,s.type,s.key)?'checked':''} ${full?'disabled':''}> ${esc(s.title.replace(/^\d+\.\s*/,''))}</label>`).join('')}</div>`:''}${!sections.length&&u>1?'<small class="muted">Todavía no hay secciones cargadas; se puede habilitar la unidad completa.</small>':''}</div>`}
function admin(){return `<section class="hero compact"><span class="eyebrow">Administración</span><h1>Panel de control</h1><p>Elegí exactamente qué unidades, capítulos y evaluaciones ve cada alumno y por cuánto tiempo.</p></section><section class="adminEditor"><div class="editorHead"><div><h2>${editing?'Editar acceso':'Nuevo acceso'}</h2><p>El acceso empieza al guardarlo.</p></div>${editing?'<button class="secondary small" data-a="resetForm">Nuevo</button>':''}</div><label class="field">Email<input id="accessEmail" type="email" value="${esc(editing?.email||'')}" placeholder="alumno@gmail.com" ${editing?'readonly':''}></label><div class="duration"><b>Duración</b><div class="durationPresets">${[['1m','1 mes'],['2m','2 meses'],['3m','3 meses'],['forever','Por siempre']].map(([k,l])=>`<button data-duration="${k}" class="${durationMode===k?'selected':''}">${l}</button>`).join('')}${editing?`<button data-duration="keep" class="${durationMode==='keep'?'selected':''}">Mantener actual</button>`:''}</div><label class="field dateField">Elegir otra fecha<input id="expiryDate" type="date" value="${customDate}"></label></div><h3 class="subheading">Permisos de Química</h3><div class="grantGrid">${UNITS.map(unitGrantCard).join('')}</div><button class="primary saveAccess" data-a="saveAccess">Guardar acceso</button></section><section class="adminList"><div class="listHead"><h2>Alumnos y testers</h2><span>${users.filter(u=>u.role!=='admin').length} registrados</span></div>${users.filter(u=>u.role!=='admin').length?users.filter(u=>u.role!=='admin').map(u=>`<div class="userRow"><div><b>${esc(u.email)}</b><small>${grantSummary(u.email)}</small></div><div><span class="status ${expiryLabel(u)==='Suspendido'||expiryLabel(u)==='Vencido'?'bad':''}">${expiryLabel(u)}</span><button class="secondary small" data-edit="${esc(u.email)}">Editar</button><button class="ghost small" data-toggle-user="${esc(u.email)}" data-active="${u.active}">${u.active?'Suspender':'Reactivar'}</button></div></div>`).join(''):'<div class="empty">Todavía no agregaste alumnos.</div>'}</section>`}
function adminSolutionsPanel(){const units=[...new Set(adminExercises.map(x=>x.unit_no))].sort((a,b)=>a-b);return `<section class="adminList solutionAdmin"><div class="listHead"><div><span class="eyebrow">Contenido</span><h2>Resoluciones de ejercicios</h2></div><span>${adminExercises.length} ejercicios</span></div>${units.map(u=>{const ex=adminExercises.filter(x=>x.unit_no===u),sol=ex.map(x=>adminSolutions.find(s=>s.exercise_id===x.id)).filter(Boolean),visible=sol.filter(s=>s.student_visible).length;return `<details class="solutionUnit"><summary><div><b>Unidad ${u} · ${UNIT_TITLES[u]||''}</b><small>${ex.length} ejercicios · ${sol.length} resueltos · ${visible} visibles</small></div><span>${sol.length===ex.length?'✓':'⚠'}</span></summary><div class="bulkActions"><button class="secondary small" data-solution-bulk="${u}" data-visible="true">Mostrar todas</button><button class="ghost small" data-solution-bulk="${u}" data-visible="false">Ocultar todas</button></div>${ex.map(x=>{const s=adminSolutions.find(y=>y.exercise_id===x.id);return `<label class="solutionToggle"><span><b>${esc(x.title)}</b><small>${s?'✓ Solución cargada':'⚠ Falta solución'}</small></span>${s?`<input type="checkbox" data-solution="${s.exercise_id}" ${s.student_visible?'checked':''}>`:''}</label>`}).join('')}</details>`}).join('')||'<div class="empty">Todavía no hay ejercicios cargados.</div>'}</section>`}
function searchModal(){const items=[{label:'Química',key:'chemistry'},{label:'Matemática',key:'math'},...UNITS.map(u=>({label:`Química · Unidad ${u} · ${UNIT_TITLES[u]||''}`,key:`unit:${u}`})),...searchItems];return `<div class="modalLayer"><div class="searchModal"><div class="searchBox">⌕<input id="q" autofocus placeholder="Buscar Boyle, densidad, Arrhenius, pH…"><button class="icon" data-a="closeSearch">×</button></div><div id="results" class="results">${items.slice(0,8).map(x=>`<button data-result="${x.key}"><b>${esc(x.label)}</b><span>›</span></button>`).join('')}</div></div></div>`}
function themeModal(){return `<div class="modalLayer"><div class="themeModal"><div class="modalTitle"><div><span class="eyebrow">Apariencia</span><h2>Personalizá CBC x SOLved</h2></div><button class="icon" data-a="closeTheme">×</button></div><div class="themeModes"><button data-mode="light" class="${mode==='light'?'selected':''}">☀ Claro</button><button data-mode="dark" class="${mode==='dark'?'selected':''}">☾ Oscuro</button></div><label class="colorField">Color principal <input id="accentColor" type="color" value="${accent}"></label><div class="swatches">${['#0f9f9a','#06b6d4','#14b8a6','#22c55e','#3b82f6','#8b5cf6','#ec4899','#f59e0b'].map(c=>`<button data-color="${c}" style="--sw:${c}"></button>`).join('')}</div><p>El color y el modo quedan guardados en este dispositivo.</p></div></div>`}
const prop=(label,value,unit='')=>`<div><small>${label}</small><b>${value||value===0?`${value}${unit}`:'Sin dato'}</b></div>`;
const esCategory=v=>({'Nonmetal':'No metal','Noble gas':'Gas noble','Alkali metal':'Metal alcalino','Alkaline earth metal':'Metal alcalinotérreo','Metalloid':'Metaloide','Halogen':'Halógeno','Post-transition metal':'Metal postransición','Transition metal':'Metal de transición','Lanthanide':'Lantánido','Actinide':'Actínido'})[v]||v;
const esState=v=>({'Solid':'Sólido','Liquid':'Líquido','Gas':'Gas','Expected to be a Solid':'Se espera sólido','Expected to be a Gas':'Se espera gas'})[v]||v;
function periodicModal(){const el=periodicElements.find(x=>x.symbol===selectedElement)||periodicElements[0];const cells=periodicElements.map(x=>`<button class="elementCell cat-${norm(x.category).replace(/\s/g,'-')} ${x.symbol===selectedElement?'selected':''}" style="grid-column:${x.column};grid-row:${x.row}" data-element="${x.symbol}" title="${x.name}"><small>${x.z}</small><b>${x.symbol}</b><em>${x.name}</em><span>${x.mass}</span></button>`).join('');return `<div class="periodicLayer" role="dialog" aria-modal="true" aria-label="Tabla periódica interactiva"><section class="periodicModal"><header><div><span class="eyebrow">HERRAMIENTA INTERACTIVA</span><h2>Tabla periódica</h2><p>Tocá un elemento para ver sus propiedades.</p></div><button class="periodicClose" data-a="closePeriodic" aria-label="Cerrar tabla periódica">× Cerrar</button></header><div class="periodicLearn"><details open><summary>¿Cómo está organizada?</summary><p>Cada casillero muestra <b>Z</b>, símbolo y masa promedio. El <b>número másico A</b> pertenece a un isótopo concreto; por eso el panel lo presenta sólo como referencia redondeada. Los <b>períodos</b> son las filas: indican el nivel principal más externo ocupado. Los <b>grupos</b> son las columnas: reúnen elementos con configuraciones de valencia semejantes y, por eso, comportamientos químicos parecidos.</p></details><details><summary>Bloques, familias y por qué se agrupan</summary><p>Los bloques <b>s, p, d y f</b> indican el tipo de subnivel que se está llenando. En el grupo 1 están los alcalinos, en el 2 los alcalinotérreos, del 3 al 12 los metales de transición, en el 17 los halógenos y en el 18 los gases nobles. Lantánidos y actínidos se muestran abajo sólo para que la tabla entre en pantalla.</p></details><details><summary>Tendencias para leer de un vistazo</summary><p>Hacia la derecha suele <b>disminuir el radio</b> y aumentar la <b>energía de ionización</b> y la <b>electronegatividad</b>. Hacia abajo aumenta el radio por la incorporación de capas; el carácter metálico suele crecer hacia abajo y hacia la izquierda.</p></details></div><div class="periodicScroll"><div class="periodicGrid" aria-label="Elementos por grupo y período">${cells}</div></div>${el?`<aside class="elementDetail"><div class="elementIdentity"><small>${el.z}</small><strong>${el.symbol}</strong><div><h3>${el.name}</h3><p>${esCategory(el.category)} · período ${el.period} · grupo ${el.group}</p></div></div><div class="propertyGrid">${prop('Número atómico Z',el.z)}${prop('Número másico A orientativo',Math.round(Number(el.mass)))}${prop('Masa atómica promedio',el.mass,' u')}${prop('Electronegatividad',el.electronegativity)}${prop('Radio atómico',el.radius,' pm')}${prop('1.ª ionización',el.ionization,' eV')}${prop('Afinidad electrónica',el.affinity,' eV')}${prop('Estados de oxidación',el.oxidation)}${prop('Estado estándar',esState(el.state))}${prop('Densidad',el.density,' g/cm³')}${prop('Fusión',el.melting,' K')}${prop('Ebullición',el.boiling,' K')}${prop('Configuración electrónica',el.configuration)}</div></aside>`:''}<footer><small>Datos: PubChem Periodic Table, National Library of Medicine.</small><button class="primary" data-a="closePeriodic">Cerrar tabla</button></footer></section></div>`}

function render(){if(!session&&!guest){app.className='';app.innerHTML=welcome();bind();return}let content=subjects();if(view==='chemistry')content=chemistry();if(view==='history')content=historyPage();if(view==='unit')content=unitPage();if(view==='math')content=math();if(view==='admin'&&isAdmin())content=admin()+adminSolutionsPanel();app.className='appShell';app.innerHTML=`${sidebar()}<div class="main">${renderTopbar()}<main class="content">${msg?`<div class="notice inline">${esc(msg)}</div>`:''}${content}</main></div><button class="periodicFab" data-a="openPeriodic" aria-label="Abrir tabla periódica">⚛ <span>Tabla periódica</span></button>${searchOpen?searchModal():''}${themeOpen?themeModal():''}${periodicOpen?periodicModal():''}`;bind();renderMath();setTimeout(renderMath,250)}
async function openUnit(target){const saved=localStorage.getItem(`cbc-unit-progress-${target}`);progressLockUntil=Date.now()+700;unit=Number(target);view='unit';side=false;await loadUnit(unit);render();setTimeout(()=>{const el=saved&&document.getElementById(`sec-${saved}`);if(el)el.scrollIntoView({block:'start'});else window.scrollTo({top:0,left:0})},80)}
function enhanceUnitPage(){if(view!=='unit')return;const sections=(sectionsByUnit[unit]||[]).filter(s=>canSection(unit,s));document.querySelector('.reviewStrip')?.remove();const map=document.querySelector('.unitMap');if(map){map.querySelector('p')?.remove();const steps=map.querySelector('.mapSteps');if(steps)steps.innerHTML=sections.map((s,i)=>`<button data-scroll="${s.key}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title.replace(/^\d+\.\s*/,''))}</button>`).join('')}document.querySelectorAll('.studySection').forEach(el=>{const key=el.dataset.section,s=sections.find(x=>x.key===key),article=el.querySelector('article');if(s&&article){const html=theorySupplement(s);if(html)article.insertAdjacentHTML('afterbegin',html)}});const flow=document.querySelector('.studyFlow');if(flow&&!document.querySelector('.mentalMap'))flow.insertAdjacentHTML('beforeend',mentalMap(sections));document.querySelectorAll('[data-concentration-type]').forEach(button=>button.onclick=()=>{const lab=button.closest('[data-sim="concentration"]');lab.dataset.concentrationType=button.dataset.concentrationType;lab.querySelectorAll('[data-concentration-type]').forEach(x=>x.classList.toggle('active',x===button));updateStudySimulator(lab)})}
function bind(){
  enhanceUnitPage();
  document.querySelector('.unitToc [data-scroll="repaso"]')?.remove();
  if(view==='unit'&&!document.querySelector('.unitToc [data-scroll="mental-map"]'))document.querySelector('.unitToc>div')?.insertAdjacentHTML('beforeend','<button data-scroll="mental-map"><span>◇</span>Mapa mental</button>');
  document.querySelectorAll('.studySection.example>article').forEach(article=>{if(article.firstElementChild?.classList.contains('exampleDisclosure'))return;const details=document.createElement('details');details.className='exampleDisclosure';details.innerHTML='<summary>Abrir ejemplo y resolución</summary>';while(article.firstChild)details.append(article.firstChild);article.append(details)});
  document.onkeydown=e=>{if(e.key==='Escape'&&periodicOpen){periodicOpen=false;render()}else if(e.key==='Escape'&&searchOpen){searchOpen=false;render()}};
  window.onscroll=()=>{if(view!=='unit'||Date.now()<progressLockUntil)return;clearTimeout(progressTimer);progressTimer=setTimeout(()=>{const sections=[...document.querySelectorAll('[data-section]')];const nearest=sections.sort((a,b)=>Math.abs(a.getBoundingClientRect().top-120)-Math.abs(b.getBoundingClientRect().top-120))[0];if(nearest)localStorage.setItem(`cbc-unit-progress-${unit}`,nearest.dataset.section)},180)};
  document.querySelectorAll('[data-v]').forEach(x=>x.onclick=async()=>{view=x.dataset.v;side=false;if(view==='admin')await loadAdmin();if(view==='history')await loadUnit(2);render();window.scrollTo({top:0,left:0})});
  document.querySelectorAll('[data-u]').forEach(x=>x.onclick=()=>openUnit(x.dataset.u));
  const on=(q,fn)=>{const x=document.querySelector(q);if(x)x.onclick=fn};
  on('[data-a="google"]',google);on('[data-a="guest"]',()=>{guest=true;localStorage.setItem('cbc-mode','guest');render()});
  on('[data-a="install"]',async()=>{if(installPrompt){installPrompt.prompt();installPrompt=null}else{msg='En Chrome: menú ⋮ → Instalar app o Agregar a pantalla principal.';render()}});
  on('[data-a="logout"]',logout);on('[data-a="openSide"]',()=>{side=true;render()});document.querySelectorAll('[data-a="closeSide"]').forEach(x=>x.onclick=()=>{side=false;render()});
  on('[data-a="search"]',()=>{searchOpen=true;render();setTimeout(()=>document.querySelector('#q')?.focus(),20)});on('[data-a="closeSearch"]',()=>{searchOpen=false;render()});
  on('[data-a="theme"]',()=>{themeOpen=true;render()});on('[data-a="closeTheme"]',()=>{themeOpen=false;render()});
  on('[data-a="openPeriodic"]',()=>{periodicOpen=true;render()});document.querySelectorAll('[data-a="closePeriodic"]').forEach(x=>x.onclick=()=>{periodicOpen=false;render()});
  document.querySelectorAll('[data-element]').forEach(x=>x.onclick=()=>{selectedElement=x.dataset.element;render();setTimeout(()=>document.querySelector('.elementDetail')?.scrollIntoView({behavior:'smooth',block:'nearest'}),20)});
  on('[data-a="saveAccess"]',saveAccess);on('[data-a="resetForm"]',resetForm);
  document.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>editUser(x.dataset.edit));document.querySelectorAll('[data-toggle-user]').forEach(x=>x.onclick=()=>toggleUser(x.dataset.toggleUser,x.dataset.active!=='true'));
  document.querySelectorAll('[data-solution]').forEach(x=>x.onchange=()=>setSolutionVisibility(x.dataset.solution,x.checked));document.querySelectorAll('[data-solution-bulk]').forEach(x=>x.onclick=()=>setUnitSolutionsVisibility(x.dataset.solutionBulk,x.dataset.visible==='true'));
  document.querySelectorAll('[data-duration]').forEach(x=>x.onclick=()=>{durationMode=x.dataset.duration;if(durationMode!=='custom')customDate='';document.querySelectorAll('[data-duration]').forEach(b=>b.classList.toggle('selected',b.dataset.duration===durationMode));});
  const date=document.querySelector('#expiryDate');if(date)date.onchange=e=>{customDate=e.target.value;durationMode='custom';document.querySelectorAll('[data-duration]').forEach(b=>b.classList.remove('selected'));};
  on('[data-a="toggleToc"]',()=>{tocOpen=!tocOpen;render()});
  document.querySelectorAll('[data-scroll]').forEach(x=>x.onclick=()=>{tocOpen=false;if(view==='unit'){progressLockUntil=Date.now()+700;localStorage.setItem(`cbc-unit-progress-${unit}`,x.dataset.scroll)}document.querySelector(`#sec-${CSS.escape(x.dataset.scroll)}`)?.scrollIntoView({behavior:'auto',block:'start'})});
  document.querySelectorAll('[data-sim]').forEach(lab=>{lab.querySelectorAll('input,select').forEach(x=>x.oninput=()=>updateSimulator(lab));updateSimulator(lab)});
  document.querySelectorAll('.inlineSimulator').forEach(lab=>{lab.querySelectorAll('input,select').forEach(x=>x.oninput=()=>updateStudySimulator(lab));lab.querySelectorAll('[data-state]').forEach(x=>x.onclick=()=>setMatterState(lab,x.dataset.state));const check=lab.querySelector('[data-check-separation]');if(check)check.onclick=()=>{const value=lab.querySelector('[data-sim-input="mixture"]').value,answers={'sand-water':'Filtración: el sólido insoluble queda retenido por el filtro.','oil-water':'Decantación: las fases inmiscibles se separan por densidad.','salt-water':'Destilación para recuperar agua, o cristalización para recuperar la sal.','ink':'Cromatografía: los pigmentos migran distinto según su afinidad.'};lab.querySelector('[data-sim-output]').textContent=answers[value]};updateStudySimulator(lab)});
  document.querySelectorAll('[data-mode]').forEach(x=>x.onclick=()=>{mode=x.dataset.mode;localStorage.setItem('cbc-theme',mode);applyTheme();render()});
  document.querySelectorAll('[data-color]').forEach(x=>x.onclick=()=>{accent=x.dataset.color;localStorage.setItem('cbc-accent',accent);applyTheme();render()});
  const ac=document.querySelector('#accentColor');if(ac)ac.oninput=e=>{accent=e.target.value;localStorage.setItem('cbc-accent',accent);applyTheme()};
  const q=document.querySelector('#q');if(q)q.oninput=e=>{const s=norm(e.target.value);const items=[{label:'Química',key:'chemistry',text:'química'},{label:'Matemática',key:'math',text:'matemática'},...UNITS.map(u=>({label:`Química · Unidad ${u} · ${UNIT_TITLES[u]||''}`,key:`unit:${u}`,text:`unidad ${u} ${UNIT_TITLES[u]||''}`})),...searchItems].filter(x=>norm(`${x.label} ${x.text||''}`).includes(s)).slice(0,60);document.querySelector('#results').innerHTML=items.map(x=>`<button data-result="${x.key}"><b>${esc(x.label)}</b><span>›</span></button>`).join('')||'<div class="empty">Sin resultados en el contenido disponible.</div>';document.querySelectorAll('[data-result]').forEach(r=>r.onclick=()=>goResult(r.dataset.result))};
  document.querySelectorAll('[data-result]').forEach(r=>r.onclick=()=>goResult(r.dataset.result));
  initSectionTracking();initStudyDeck();
}
async function goResult(k){let anchor='';if(k.startsWith('periodic:')){selectedElement=k.split(':')[1];periodicOpen=true;searchOpen=false;render();return}if(k.startsWith('unit:')){unit=Number(k.split(':')[1]);view='unit'}else if(k.startsWith('section:')){const p=k.split(':');unit=Number(p[1]);anchor=`sec-${p.slice(2).join(':')}`;view='unit'}else if(k.startsWith('exercise:')){const p=k.split(':');unit=Number(p[1]);anchor=`exercise-${p[2]}`;view='unit'}else view=k;searchOpen=false;render();if(view==='history'){await loadUnit(2);render()}if(view==='unit'){await loadUnit(unit);render();if(anchor)setTimeout(()=>document.getElementById(anchor)?.scrollIntoView({behavior:'smooth'}),60)}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');
init();




